220	/* The original scanline fill with a plain insertion sort, kept as a reference
221	 * so changes to the sort can be checked for identical output. */
222	static void reference_fill_polygon(Canvas *cv, const int *xy, int n,
223	                                   uint16_t color) {
224	  if (n < 3) return;
225	  long ymin = xy[1], ymax = xy[1];
226	  for (int i = 1; i < n; i++) {
227	    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
228	    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
229	  }
230	  if (ymin < 0) ymin = 0;
231	  if (ymax >= cv->h) ymax = cv->h - 1;
232	  double *xs = malloc((size_t)n * sizeof(double));
233	  for (long yy = ymin; yy <= ymax; yy++) {
234	    int nx = 0;
235	    double sy = yy + 0.5;
236	    for (int i = 0, j = n - 1; i < n; j = i++) {
237	      double yi = xy[2 * i + 1], yj = xy[2 * j + 1];
238	      if ((yi <= sy && yj > sy) || (yj <= sy && yi > sy)) {
239	        double t = (sy - yi) / (yj - yi);
240	        xs[nx++] = xy[2 * i] + t * (xy[2 * j] - xy[2 * i]);
241	      }
242	    }
243	    for (int a = 1; a < nx; a++)
244	      for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
245	        double tmp = xs[b];
246	        xs[b] = xs[b - 1];
247	        xs[b - 1] = tmp;
248	      }
249	    for (int k = 0; k + 1 < nx; k += 2) {
250	      long xa = (long)ceil(xs[k] - 0.5), xb = (long)ceil(xs[k + 1] - 0.5) - 1;
251	      if (xa < 0) xa = 0;
252	      if (xb >= cv->w) xb = cv->w - 1;
253	      for (long x = xa; x <= xb; x++) cv->px[yy * cv->w + x] = color;
254	    }
255	  }
256	  free(xs);
257	}
