    for (int i = 0; i < ne; i++) {
      PolyEdge *e = &edges[i];
      if (y < e->ylo || y >= e->yhi) continue;
      if (e->row == y - 1) {
        e->col += e->step_col;
        e->rem += e->step_rem;
        if (e->rem >= e->den) e->rem -= e->den, e->col++;
