import re
import sys
from pathlib import Path

d = Path(sys.argv[1])
vals = {}
lines = {}
for v in sys.argv[2:]:
    for raw in (d / f"bench{v}.log").read_text().splitlines():
        m = re.match(r"bench (\S+) total_ms=\S+ per_us=(\S+)", raw)
        if m:
            vals.setdefault(m.group(1), {})[v] = float(m.group(2))
        elif "dcache line" in raw:
            lines[v] = lines.get(v, []) + [raw.split("line=")[1]]
print("dcache line before/after per variant:", lines)
print(f"{'test':30}" + "".join(f"{('v' + v):>10}" for v in sys.argv[2:]))
for name, row in vals.items():
    print(f"{name:30}" + "".join(f"{row.get(v, float('nan')):10.4f}" for v in sys.argv[2:]))

