""","""  const bool keep32 = hack->sync_to_refresh || hack->dcache_line32;
""")
s=s.replace(""" * the old copy time. Discrete draws many short spans, which 64 bytes slow (-5%
 * fps).""",""" * the old copy time. A hack with many short spans (Discrete, -5% fps) asks for
 * dcache_line32.""")
open(p,'w').write(s)
E
