/* Builds the unmodified deluxe.c with resources that suit the shim. Its
 * `transparent` default draws through colour-plane masks, which an RGB565
 * canvas cannot do, and its `doubleBuffer` default draws into two pixmaps,
 * which would cost 868 KB and a full-frame copy each frame.
 *
 * Its circles are 50 pixels wide arcs up to 700 across. The shim strokes an
 * arc as a polyline of about a thousand wide segments, each filled a row at a
 * time, and that was 94% of a frame (2 to 5 fps); stroke_circle fills the same
 * ring in two spans a row. */
#include "screenhack.h"
#include "x11shim/stroke.h"

static int deluxe_draw_arc(Display *dpy, Drawable d, GC gc, int x, int y,
                           unsigned int w, unsigned int h, int angle1,
                           int angle2) {
  if (gc->line_width > 1 && w == h && (angle2 >= 360 * 64 || angle2 <= -360 * 64)) {
    stroke_circle(dpy->canvas, gc, x, y, w);
    return 0;
  }
  return XDrawArc(dpy, d, gc, x, y, w, h, angle1, angle2);
}

#define XDrawArc deluxe_draw_arc

/* Upstream's translucent path draws each shape at alpha 0xCC of 0xFF; 26 of 32
 * is the same weight. Only the throbbers' GCs set a line width. */
#define DELUXE_ALPHA 26
static GC deluxe_create_gc(Display *dpy, Drawable d, unsigned long mask,
                           XGCValues *v) {
  GC gc = XCreateGC(dpy, d, mask, v);
  if (gc && (mask & GCLineWidth)) gc->alpha = DELUXE_ALPHA;
  return gc;
}

#define XCreateGC deluxe_create_gc

#undef XSCREENSAVER_MODULE
#define XSCREENSAVER_MODULE(CLASS, PREFIX)

#include "deluxe/deluxe.c"

static const char *const kDeluxeOverrides[] = {"*transparent: False",
                                               "*doubleBuffer: False", NULL};

const HackEntry deluxe_hack = {"Deluxe", deluxe_defaults, deluxe_init,
                               deluxe_draw, deluxe_free, NULL,
                               kDeluxeOverrides};
# ifdef HAVE_DOUBLE_BUFFER_EXTENSION
  Bool dbeclear_p;
  XdbeBackBuffer backb;
# endif /* HAVE_DOUBLE_BUFFER_EXTENSION */
};

struct throbber {
  int x, y;
  int size;
  int max_size;
  int thickness;
  int speed;
  int fuse;
  GC gc;
  void (*draw) (struct state *, Drawable, struct throbber *);
};


static void
draw_star (struct state *st, Drawable w, struct throbber *t)
{
  XPoint points[11];
  int x = t->x;
  int y = t->y;

  /*
    The following constant is really:
      sqrt(5 - sqrt(5)) / sqrt(25 - 11 * sqrt(5))

    Reference: http://mathworld.wolfram.com/Pentagram.html
  */
  int s = t->size * 2.6180339887498985;
  int s2 = t->size;
  double c = M_PI * 2;
  double o = -M_PI / 2;

  points[0].x = x + s  * cos(o + 0.0*c); points[0].y = y + s  * sin(o + 0.0*c);
  points[1].x = x + s2 * cos(o + 0.1*c); points[1].y = y + s2 * sin(o + 0.1*c);
  points[2].x = x + s  * cos(o + 0.2*c); points[2].y = y + s  * sin(o + 0.2*c);
  points[3].x = x + s2 * cos(o + 0.3*c); points[3].y = y + s2 * sin(o + 0.3*c);
  points[4].x = x + s  * cos(o + 0.4*c); points[4].y = y + s  * sin(o + 0.4*c);
  points[5].x = x + s2 * cos(o + 0.5*c); points[5].y = y + s2 * sin(o + 0.5*c);
  points[6].x = x + s  * cos(o + 0.6*c); points[6].y = y + s  * sin(o + 0.6*c);
  points[7].x = x + s2 * cos(o + 0.7*c); points[7].y = y + s2 * sin(o + 0.7*c);
  points[8].x = x + s  * cos(o + 0.8*c); points[8].y = y + s  * sin(o + 0.8*c);
  points[9].x = x + s2 * cos(o + 0.9*c); points[9].y = y + s2 * sin(o + 0.9*c);
  points[10] = points[0];

  XDrawLines (st->dpy, w, t->gc, points, countof(points), CoordModeOrigin);
}

static void
draw_circle (struct state *st, Drawable w, struct throbber *t)
{
  XDrawArc (st->dpy, w, t->gc,
            t->x - t->size / 2,
            t->y - t->size / 2,
            t->size, t->size,
            0, 360*64);
}

static void
draw_hlines (struct state *st, Drawable w, struct throbber *t)
{
  XDrawLine (st->dpy, w, t->gc, 0,
             t->y - t->size, t->max_size,
             t->y - t->size);
  XDrawLine (st->dpy, w, t->gc, 0,
             t->y + t->size, t->max_size,
             t->y + t->size);
}
/* Builds hopalong.c in single precision: its orbit maths is `double`, which
 * runs in software on the ESP32-S3. Its decimal literals are made floats at
 * build time (tools/float_literals.py), and MAXRAND and M_PI are floats
 * (single_constants.h). */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "xlockmore.h"

#include "hacks/single_precision.h"
#include "hacks/single_constants.h"

#include "hopalong_floatlit.c"

